// Category B — no headless timer exists, and the behaviour is one clock. The look is Badge's `urgency`
// chip; Badge stays static and this component only re-renders it once a second.
//
// Accessibility (WAI-ARIA 1.2 `timer`): the root is `role="timer"`, whose live region is `off`, so a
// screen reader is never interrupted by the ticking text; it reads the value when the user reaches it.
// When `label` is given, the ticking text is hidden from assistive technology and the timer is named by
// `label` instead, computed at minute granularity so it never names a second that has already gone.
import { useEffect, useRef, useState } from "react";
import type { ReactNode, Ref } from "react";
import { Badge } from "./Badge";
import type { BadgeProps } from "./Badge";

/** Time left, split for a format. `hh`, `mm` and `ss` are the two-digit forms of the three numbers. */
export interface CountdownTime {
  /** Milliseconds left; 0 once it has ended. */
  remaining: number;
  days: number;
  hours: number;
  minutes: number;
  seconds: number;
  hh: string;
  mm: string;
  ss: string;
}

export interface CountdownProps
  extends Omit<BadgeProps, "variant" | "category" | "children" | "role" | "ref"> {
  /** When it ends, as a `Date` or epoch milliseconds. */
  endsAt: Date | number;
  /**
   * The visible text for a time left, in the product's language, for example
   * `` (t) => `${t.days}일 ${t.hh}:${t.mm}:${t.ss}뒤 종료` ``.
   */
  format: (time: CountdownTime) => ReactNode;
  /**
   * The accessible name, from the time left rounded up to the minute (its `seconds` is always 0).
   * Optional: without it, assistive technology reads the visible text.
   */
  label?: (time: CountdownTime) => string;
  /**
   * A fixed clock, as a `Date` or epoch milliseconds. When set nothing ticks and the time left is
   * `endsAt − now`, for a still render (a story, a test, a server snapshot).
   */
  now?: Date | number;
  /** Called once when the time left reaches 0, including at mount if `endsAt` has already passed. */
  onEnd?: () => void;
  /** Forwarded to the Badge's <span> DOM node. */
  ref?: Ref<HTMLSpanElement>;
}

const pad = (n: number) => String(n).padStart(2, "0");

/** Whole seconds, rounded up, so the last second reads 00:00:01 until the end rather than 00:00:00. */
function toTime(remaining: number, unit = 1000): CountdownTime {
  const total = Math.ceil(remaining / unit) * (unit / 1000);
  const days = Math.floor(total / 86400);
  const hours = Math.floor(total / 3600) % 24;
  const minutes = Math.floor(total / 60) % 60;
  const seconds = total % 60;
  return { remaining, days, hours, minutes, seconds, hh: pad(hours), mm: pad(minutes), ss: pad(seconds) };
}

export function Countdown({ endsAt, format, label, now, onEnd, ...props }: CountdownProps) {
  const end = +endsAt;
  const fixed = now === undefined ? undefined : +now;
  // Read at render, so a server render and the hydrating client disagree by the seconds between them;
  // the text node below accepts that one difference, which is React's sanctioned case (a timestamp).
  const [clock, setClock] = useState(() => Date.now());
  const remaining = Math.max(0, end - (fixed ?? clock));

  useEffect(() => {
    if (fixed !== undefined) return;
    // Recompute from the wall clock each time, never decrement, so a throttled background tab or a
    // late timer cannot drift; each wake lands on the next whole second before `end`.
    const wait = (t: number) => Math.max(0, (end - t) % 1000) || 1000;
    let id: ReturnType<typeof setTimeout>;
    const step = () => {
      const t = Date.now();
      setClock(t);
      if (t < end) id = setTimeout(step, wait(t));
    };
    id = setTimeout(step, wait(Date.now()));
    return () => clearTimeout(id);
  }, [end, fixed]);

  const onEndRef = useRef(onEnd);
  useEffect(() => {
    onEndRef.current = onEnd;
  });
  const ended = remaining === 0;
  useEffect(() => {
    if (ended) onEndRef.current?.();
  }, [ended, end]);

  const time = toTime(remaining);
  const name = label?.(toTime(remaining, 60000));
  return (
    <Badge
      {...props}
      variant="urgency"
      role="timer"
      aria-live="off"
      aria-label={name ?? props["aria-label"]}
      // A figure that re-renders in place keeps its width: tabular digits (reset.css).
      className={props.className ? `sd-tabular ${props.className}` : "sd-tabular"}
    >
      <span aria-hidden={name ? true : undefined} suppressHydrationWarning>
        {format(time)}
      </span>
    </Badge>
  );
}
